/* Rentcam promo schedule runtime v8 — scheduled labels/discounts/banners without observer loop */
(function(){
  if(location.pathname.startsWith('/cms'))return;
  const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Math.max(0,Number(n)||0));
  const cfg=()=>window.RENTCAM_CMS_CONFIG||null;
  const dayStart=s=>s?new Date(s+'T00:00:00').getTime():null;
  const dayEnd=s=>s?new Date(s+'T23:59:59').getTime():null;
  const inRange=(a,b)=>{const n=Date.now(),x=dayStart(a),y=dayEnd(b);return(!x||n>=x)&&(!y||n<=y)};
  function meta(id){const c=cfg();if(!c)return null;return(c.customProducts||[]).find(x=>String(x.id)===String(id))||(c.productOverrides||{})[id]||null}
  const visible=x=>!x||((x.active!==false)&&(x.deleted!==true)&&inRange(x.publishDate,x.unpublishDate));
  const labelOn=x=>!!x?.labelText&&inRange(x.labelStart,x.labelEnd);
  const discountOn=x=>Number(x?.discountPercent)>0&&inRange(x.discountStart,x.discountEnd);
  function idFromCard(card){let id=card.getAttribute('data-product-id')||card.dataset?.productId||'';if(!id){const m=(card.getAttribute('onclick')||'').match(/\/produk\/([^'\")]+)/);if(m)id=m[1]}return decodeURIComponent(id||'')}
  function style(){if(document.getElementById('v8promo'))return;const s=document.createElement('style');s.id='v8promo';s.textContent=`.v8-product-label{position:absolute;z-index:5;left:10px;top:10px;background:#111;color:#fff;padding:7px 10px;border-radius:999px;font-size:10px;font-weight:900}.v8-discount-label{background:#f26a21}.v8-old-price{text-decoration:line-through;color:#929292;font-weight:600;margin-right:6px}.v8-new-price{color:#d84d0f;font-weight:900}.v8-detail-promo{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 14px}.v8-detail-promo span{display:inline-flex;padding:7px 10px;border-radius:999px;font-size:11px;font-weight:900;background:#111;color:#fff}.v8-detail-promo span.sale{background:#f26a21}.v8-hero-label{display:inline-flex;margin-bottom:10px;padding:7px 10px;border-radius:999px;background:#f26a21;color:#fff;font-size:10px;font-weight:900;letter-spacing:.05em}`;document.head.appendChild(s)}
  function parsePrice(el){const t=el?.textContent||'';const m=t.replace(/\./g,'').replace(/,/g,'').match(/(?:Rp\s*)?(\d{2,})/i);return m?Number(m[1]):0}
  function patchCard(card){const id=idFromCard(card);if(!id)return;const x=meta(id);if(!x)return;const show=visible(x);card.style.display=show?'':'none';if(!show)return;const holder=card.querySelector('.pimg,.home-category-image')||card;holder.style.position='relative';const labelText=labelOn(x)?x.labelText:(discountOn(x)?(x.discountLabel||('DISKON '+Number(x.discountPercent)+'%')):'');let lab=holder.querySelector('.v8-product-label');if(labelText){if(!lab){lab=document.createElement('span');lab.className='v8-product-label';holder.appendChild(lab)}if(lab.textContent!==labelText)lab.textContent=labelText;lab.className='v8-product-label'+(discountOn(x)?' v8-discount-label':'')}else if(lab)lab.remove();const pr=card.querySelector('.price');if(pr){if(!pr.dataset.v8Original)pr.dataset.v8Original=pr.innerHTML;if(discountOn(x)){const base=Number(x.price)||Number(pr.dataset.v8Base)||parsePrice(pr);if(base){pr.dataset.v8Base=base;const cut=Math.round(base*(1-Number(x.discountPercent)/100));const html=`<span class="v8-old-price">${money(base)}</span><span class="v8-new-price">${money(cut)}</span> <small>/ full day</small>`;if(pr.innerHTML!==html)pr.innerHTML=html}}else if(pr.dataset.v8Original&&pr.innerHTML!==pr.dataset.v8Original)pr.innerHTML=pr.dataset.v8Original}}
  function patchCards(){document.querySelectorAll('#app .pcard,#app [data-product-id],#app .home-category-card').forEach(patchCard)}
  function currentId(){const m=location.pathname.match(/^\/produk\/([^/?#]+)/);return m?decodeURIComponent(m[1]):''}
  function patchDetail(){const id=currentId();if(!id)return;const x=meta(id);if(!x)return;const app=document.getElementById('app');if(!visible(x)){const root=app?.querySelector('.page')||app;if(root&&root.dataset.v8Unavailable!=='1'){root.dataset.v8Unavailable='1';root.innerHTML='<div class="container" style="padding:80px 0"><h1>Produk tidak tersedia</h1><p>Produk ini sedang dinonaktifkan atau berada di luar jadwal tampil.</p><button class="btn" onclick="go(\'/produk\')">Kembali ke Rentals</button></div>'}return}const h1=app?.querySelector('h1');if(!h1)return;const sig=[labelOn(x)?x.labelText:'',discountOn(x)?(x.discountLabel||('DISKON '+Number(x.discountPercent)+'%')):''].join('|');let box=h1.parentElement?.querySelector('.v8-detail-promo');if(!sig){if(box)box.remove();return}if(!box){box=document.createElement('div');box.className='v8-detail-promo';h1.insertAdjacentElement('afterend',box)}if(box.dataset.sig===sig)return;box.dataset.sig=sig;box.innerHTML='';if(labelOn(x))box.insertAdjacentHTML('beforeend',`<span>${String(x.labelText).replace(/</g,'&lt;')}</span>`);if(discountOn(x))box.insertAdjacentHTML('beforeend',`<span class="sale">${String(x.discountLabel||('DISKON '+Number(x.discountPercent)+'%')).replace(/</g,'&lt;')}</span>`)}
  function bannerValid(x){return x?.active!==false&&x?.deleted!==true&&inRange(x?.startDate,x?.endDate)}
  function patchHero(){if(location.pathname!=='/')return;const c=cfg(),hero=document.querySelector('#app .hero');if(!c||!hero||!Array.isArray(c.banners)||!c.banners.length)return;const valid=c.banners.filter(bannerValid);if(!valid.length){hero.style.display='none';return}hero.style.display='';const title=hero.querySelector('h1')?.textContent?.trim()||'';const cur=c.banners.find(x=>(x.title||'').trim()===title);const b=cur&&bannerValid(cur)?cur:valid[0];if(!b)return;const sig=JSON.stringify([b.id,b.title,b.text,b.subtitle,b.image,b.promoLabel,b.discountPercent,b.startDate,b.endDate]);if(hero.dataset.v8BannerSig===sig)return;hero.dataset.v8BannerSig=sig;const h=hero.querySelector('h1'),p=hero.querySelector('p'),small=hero.querySelector('small');if(h&&b.title&&h.textContent!==b.title)h.textContent=b.title;if(p&&(b.text||b.subtitle)&&p.textContent!==(b.text||b.subtitle))p.textContent=b.text||b.subtitle;if(small&&(b.ey||b.kicker)&&small.textContent!==(b.ey||b.kicker))small.textContent=b.ey||b.kicker;if(b.image)hero.style.backgroundImage=`url('${b.image}')`;let lab=hero.querySelector('.v8-hero-label');const txt=b.promoLabel||(Number(b.discountPercent)>0?('PROMO '+Number(b.discountPercent)+'%'):'');if(txt){if(!lab){lab=document.createElement('span');lab.className='v8-hero-label';hero.querySelector('.container')?.prepend(lab)}if(lab&&lab.textContent!==txt)lab.textContent=txt}else if(lab)lab.remove()}
  function run(){style();patchCards();patchDetail();patchHero()}
  function scheduled(){setTimeout(run,70);setTimeout(run,300);setTimeout(run,900)}
  document.addEventListener('rentcam-cms-updated',scheduled);document.addEventListener('rentcam-route-change',scheduled);addEventListener('popstate',scheduled);scheduled();
})();